local UIFeelingCommunicationRoleNode = Class("UIFeelingCommunicationRoleNode")
function UIFeelingCommunicationRoleNode:__init() 
    self._curCatId = nil
    self._index = nil
    self._clickCb = nil
end

function UIFeelingCommunicationRoleNode:__delete()
    self._curCatId = nil
    self._index = nil
    self._clickCb = nil
end

function UIFeelingCommunicationRoleNode:Awake()
    SetButtonAction(self.ImgBg, Bind(self, self.OnSelectCat))
end

function UIFeelingCommunicationRoleNode:Start()
end

function UIFeelingCommunicationRoleNode:Refresh(catId, clickCb, index)
    local data = phoneComp:GetCatDataById(catId)
    if not data then
        return
    end

    local vo = PhoneUtils.GetCatVo(data.catId)
    if not vo then
        return
    end
    self._index = checkNumber(index)
    self._clickCb = clickCb
    self._curCatId = catId

    self.Root.anchoredPosition = Vector2(0, 0)
    CfUtils.FillText(self.TxtName, PhoneUtils.GetRoleCurName(data.catId))
    CfUtils.FillText(self.TxtContent, PhoneUtils.GetNewMessageText(data.catId))
    CfUtils.FillImage(self.ImgBg, "UIAtlas/Feeling/Communication/feeling_btn_role_bg_default.png")
    local skinCardId = PhoneUtils.GetRoleCurCardSkinId(data.catId)
    CfUtils.FillImage(self.ImgheadIcon, CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId))

    local redGo = GameUtils.GetRedPointGo(self.Root)
    if redGo then
        if PhoneUtils.IsCatHasNewTalkCount(data.catId) then
            KTool.SetActive(redGo, true)
        else
            KTool.SetActive(redGo, false)
        end
    end
    KTool.SetActive(self.Root, true)
end

--刷新选中状态
function UIFeelingCommunicationRoleNode:RefreshSelect()
    CfUtils.FillText(self.TxtContent, "")
    self:PlaySelectAnimator()

    local redGo = GameUtils.GetRedPointGo(self.Root)
    if redGo then
        if PhoneUtils.IsCatHasNewTalkCount(self._curCatId) then
            KTool.SetActive(redGo, true)
        else
            KTool.SetActive(redGo, false)
        end
    end
end

--刷新未选中状态
function UIFeelingCommunicationRoleNode:RefreshUnSelect()
    CfUtils.FillText(self.TxtContent, PhoneUtils.GetNewMessageText(self._curCatId))
    self:PlayUnSelectAnimator()
end

--播放动画
function UIFeelingCommunicationRoleNode:PlaySelectAnimator()
    local rootGo = self.Root:GetComponent(typeof(Animator))
    rootGo:Play("FeelingCommunicationDialogCharacterNodeSelect")
end

function UIFeelingCommunicationRoleNode:PlayUnSelectAnimator()
    local rootGo = self.Root:GetComponent(typeof(Animator))
    rootGo:Play("FeelingCommunicationDialogCharacterNodeUnselect")
end

function UIFeelingCommunicationRoleNode:OnSelectCat()
    if self._clickCb then
        self._clickCb()
    end
end

function UIFeelingCommunicationRoleNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingCommunicationRoleNode
